FOODS_BY_CITY=[
 {"name":"Kranjska klobasa","name_en":"Carniolan Sausage","name_fr":"Saucisse de Carniole","name_es":"Salchicha de Carniola","description":"Salsiccia IGP di maiale e pancetta, leggermente affumicata e cotta senza farla spaccare, servita con senape, rafano e pane. La grana deve restare succosa e compatta, con affumicatura misurata.","description_en":"Protected pork-and-bacon sausage, lightly smoked and gently heated so it does not split, served with mustard, horseradish and bread. It should remain juicy and firm with restrained smoke.","description_fr":"Saucisse protégée de porc et lard, légèrement fumée et chauffée sans éclater, servie avec moutarde, raifort et pain. Elle doit rester juteuse, ferme et peu fumée.","description_es":"Salchicha protegida de cerdo y panceta, ligeramente ahumada y calentada sin romperse, servida con mostaza, rábano picante y pan. Debe quedar jugosa, firme y con humo moderado.","ingredients":["maiale","pancetta","aglio","pepe","sale"],"ingredients_en":["pork","bacon","garlic","pepper","salt"],"ingredients_fr":["porc","lard","ail","poivre","sel"],"ingredients_es":["cerdo","panceta","ajo","pimienta","sal"],"places":["Klobasarna Ljubljana","Gostilna Sokol Ljubljana","Druga Violina Ljubljana"]},
 {"name":"Ljubljanski štruklji","name_en":"Ljubljana Štruklji","name_fr":"Štruklji de Ljubljana","name_es":"Štruklji de Liubliana","description":"Rotoli di pasta bolliti o cotti al forno con ripieni dolci o salati di ricotta, noci, dragoncello o mela. La pasta sottile deve contenere un ripieno umido e riconoscibile senza diventare pesante.","description_en":"Rolled dough, boiled or baked, with sweet or savoury fillings such as curd cheese, walnuts, tarragon or apple. Thin dough should hold a moist distinct filling without becoming heavy.","description_fr":"Rouleaux de pâte bouillis ou cuits au four, garnis de fromage blanc, noix, estragon ou pomme, en version salée ou sucrée. La pâte fine doit contenir une farce moelleuse et nette.","description_es":"Rollos de masa hervidos u horneados con rellenos dulces o salados de requesón, nueces, estragón o manzana. La masa fina debe contener relleno húmedo y reconocible sin pesadez.","ingredients":["farina","ricotta","uova","burro","ripieno stagionale"],"ingredients_en":["flour","curd cheese","eggs","butter","seasonal filling"],"ingredients_fr":["farine","fromage blanc","œufs","beurre","garniture saisonnière"],"ingredients_es":["harina","requesón","huevos","mantequilla","relleno estacional"],"places":["Moji Štruklji Slovenije Ljubljana","Gostilna na Gradu Ljubljana","Gostilna Sokol Ljubljana"]},
 {"name":"Idrijski žlikrofi","name_en":"Idrija Dumplings","name_fr":"Žlikrofi d'Idrija","name_es":"Žlikrofi de Idrija","description":"Piccoli ravioli protetti, modellati a cappello e ripieni di patate, cipolla ed erbe, serviti con sughi di carne o burro. Pur originari di Idrija, rappresentano bene la cucina slovena nell'offerta della capitale.","description_en":"Protected small hat-shaped dumplings filled with potato, onion and herbs, served with meat sauce or butter. Though from Idrija, they represent Slovenian cooking well in the capital.","description_fr":"Petits raviolis protégés en forme de chapeau, farcis de pommes de terre, oignon et herbes, servis avec sauce de viande ou beurre. Originaires d'Idrija, ils représentent bien la cuisine slovène dans la capitale.","description_es":"Pequeñas pastas protegidas con forma de sombrero, rellenas de patata, cebolla y hierbas, servidas con salsa de carne o mantequilla. Originarias de Idrija, representan bien la cocina eslovena en la capital.","ingredients":["farina","patate","cipolla","erbe","uova"],"ingredients_en":["flour","potatoes","onion","herbs","eggs"],"ingredients_fr":["farine","pommes de terre","oignon","herbes","œufs"],"ingredients_es":["harina","patatas","cebolla","hierbas","huevos"],"places":["Gostilna na Gradu Ljubljana","Strelec Restaurant Ljubljana","Slovenska Hiša Ljubljana"]},
 {"name":"Jota","name_en":"Jota Stew","name_fr":"Soupe jota","name_es":"Guiso jota","description":"Zuppa densa del Carso con crauti o rape fermentate, fagioli, patate e spesso carne affumicata. Acidità e amido devono equilibrarsi: è un piatto invernale contadino, sostanzioso ma non monotono.","description_en":"A thick Karst stew of sauerkraut or fermented turnip, beans, potatoes and often smoked meat. Acidity and starch should balance in this substantial but varied winter dish.","description_fr":"Soupe épaisse du Karst avec choucroute ou navet fermenté, haricots, pommes de terre et souvent viande fumée. Acidité et amidon doivent s'équilibrer dans ce plat paysan d'hiver.","description_es":"Guiso espeso del Karst con chucrut o nabo fermentado, alubias, patatas y a menudo carne ahumada. Acidez y almidón deben equilibrarse en este plato campesino invernal.","ingredients":["crauti","fagioli","patate","carne affumicata"],"ingredients_en":["sauerkraut","beans","potatoes","smoked meat"],"ingredients_fr":["choucroute","haricots","pommes de terre","viande fumée"],"ingredients_es":["chucrut","alubias","patatas","carne ahumada"],"places":["Gujžina Ljubljana","Gostilna Sokol Ljubljana","Druga Violina Ljubljana"]},
 {"name":"Potica","name_en":"Potica Nut Roll","name_fr":"Potica aux noix","name_es":"Potica de nueces","description":"Pasta lievitata arrotolata attorno a noci, miele, dragoncello o altri ripieni e cotta nello stampo ad anello. Una buona fetta mostra spirali regolari, impasto soffice e ripieno aromatico non asciutto.","description_en":"Yeasted dough rolled around walnut, honey, tarragon or other fillings and baked in a ring mould. A good slice shows even spirals, soft dough and an aromatic filling that is not dry.","description_fr":"Pâte levée roulée autour de noix, miel, estragon ou autres garnitures puis cuite en moule annulaire. Une bonne tranche montre spirales régulières, pâte moelleuse et farce parfumée non sèche.","description_es":"Masa fermentada enrollada con nueces, miel, estragón u otros rellenos y horneada en molde anular. Una buena porción muestra espirales regulares, masa tierna y relleno aromático no seco.","ingredients":["farina","noci","burro","uova","miele"],"ingredients_en":["flour","walnuts","butter","eggs","honey"],"ingredients_fr":["farine","noix","beurre","œufs","miel"],"ingredients_es":["harina","nueces","mantequilla","huevos","miel"],"places":["Butik lePotica Ljubljana","Zvezda Ljubljana","Slovenska Hiša Ljubljana"]},
 {"name":"Prekmurska gibanica","name_en":"Prekmurje Layer Cake","name_fr":"Gibanica du Prekmurje","name_es":"Gibanica de Prekmurje","description":"Dolce protetto a strati alternati di papavero, ricotta, noci e mele separati da pasta sottile. È ricco ma deve mantenere distinti i quattro ripieni, con acidità della mela che alleggerisce burro e semi.","description_en":"A protected layered cake alternating poppy seed, curd cheese, walnut and apple fillings between thin pastry. Rich yet balanced, it should keep all four fillings distinct, with apple acidity lightening butter and seeds.","description_fr":"Gâteau protégé en couches alternant pavot, fromage blanc, noix et pommes entre fines pâtes. Riche mais équilibré, il doit garder les quatre garnitures distinctes, l'acidité de la pomme allégeant beurre et graines.","description_es":"Pastel protegido por capas alternas de amapola, requesón, nuez y manzana entre masa fina. Rico pero equilibrado, debe mantener los cuatro rellenos diferenciados, con la acidez de manzana aligerando mantequilla y semillas.","ingredients":["semi di papavero","ricotta","noci","mele","pasta fillo"],"ingredients_en":["poppy seeds","curd cheese","walnuts","apples","thin pastry"],"ingredients_fr":["graines de pavot","fromage blanc","noix","pommes","pâte fine"],"ingredients_es":["semillas de amapola","requesón","nueces","manzanas","masa fina"],"places":["Gujžina Ljubljana","Gostilna Sokol Ljubljana","Zvezda Ljubljana"]},
 {"name":"Ajdovi žganci","name_en":"Buckwheat Žganci","name_fr":"Žganci de sarrasin","name_es":"Žganci de trigo sarraceno","description":"Grumi morbidi di farina di grano saraceno cotti e sgranati, con ciccioli, latte acido o stufati. La consistenza rustica assorbe i sughi e racconta una cucina montana basata su cereali resistenti.","description_en":"Soft crumbled buckwheat dumplings served with cracklings, sour milk or stews. Their rustic texture absorbs sauces and reflects mountain cooking based on hardy grains.","description_fr":"Morceaux tendres de farine de sarrasin cuits puis émiettés, servis avec grattons, lait aigre ou ragoûts. Leur texture rustique absorbe les sauces et raconte une cuisine montagnarde de céréales résistantes.","description_es":"Grumos tiernos de harina de trigo sarraceno cocidos y desmenuzados, con chicharrones, leche agria o guisos. Su textura rústica absorbe salsas y refleja cocina montañesa de cereales resistentes.","ingredients":["farina di grano saraceno","acqua","sale","ciccioli"],"ingredients_en":["buckwheat flour","water","salt","cracklings"],"ingredients_fr":["farine de sarrasin","eau","sel","grattons"],"ingredients_es":["harina de trigo sarraceno","agua","sal","chicharrones"],"places":["Gostilna Čad Ljubljana","Gostilna Pri Kuklju Ljubljana","Gostilna Sokol Ljubljana"]},
 {"name":"Šmorn","name_en":"Slovenian Shredded Pancake","name_fr":"Crêpe déchirée slovène","name_es":"Tortita troceada eslovena","description":"Una frittella spessa viene spezzata in padella, caramellata e servita con zucchero e composta. Parente del Kaiserschmarrn, deve restare soffice dentro e avere bordi dorati, non essere un impasto asciutto.","description_en":"A thick pancake is torn in the pan, caramelised and served with sugar and compote. Related to Kaiserschmarrn, it should stay fluffy inside with golden edges rather than becoming dry.","description_fr":"Une crêpe épaisse est déchirée à la poêle, caramélisée et servie avec sucre et compote. Cousine du Kaiserschmarrn, elle doit rester moelleuse avec bords dorés, jamais sèche.","description_es":"Una tortita gruesa se rompe en la sartén, carameliza y sirve con azúcar y compota. Pariente del Kaiserschmarrn, debe quedar esponjosa por dentro y dorada en los bordes, no seca.","ingredients":["farina","uova","latte","burro","zucchero"],"ingredients_en":["flour","eggs","milk","butter","sugar"],"ingredients_fr":["farine","œufs","lait","beurre","sucre"],"ingredients_es":["harina","huevos","leche","mantequilla","azúcar"],"places":["Gostilna na Gradu Ljubljana","Moji Štruklji Ljubljana","Gostilna Rožnik Ljubljana"]},
]

CULTURE_FACTS=[
 fact("🐉",n("Il drago è protettore, non solo souvenir","The dragon is a guardian, not just a souvenir","Le dragon est un gardien, pas seulement un souvenir","El dragón es guardián, no solo recuerdo"),n("La leggenda collega Giasone e gli Argonauti alla palude; oggi il drago compare su stemma, ponte e identità cittadina.","Legend links Jason and the Argonauts to the marsh; today the dragon appears on the coat of arms, bridge and civic identity.","La légende relie Jason et les Argonautes aux marais; aujourd'hui le dragon figure sur blason, pont et identité urbaine.","La leyenda vincula a Jasón y los Argonautas con la marisma; hoy el dragón aparece en escudo, puente e identidad urbana.")),
 fact("📐",n("Plečnik progettò una città come opera totale","Plečnik designed the city as a total work","Plečnik conçut la ville comme œuvre totale","Plečnik diseñó la ciudad como obra total"),n("Ponti, mercati, argini, biblioteca e dettagli urbani formano una rete coerente oggi riconosciuta dall'UNESCO.","Bridges, markets, embankments, library and urban details form a coherent network now recognized by UNESCO.","Ponts, marchés, quais, bibliothèque et détails urbains forment un réseau cohérent aujourd'hui reconnu par l'UNESCO.","Puentes, mercados, riberas, biblioteca y detalles urbanos forman una red coherente hoy reconocida por la UNESCO.")),
 fact("🌳",n("La natura entra nel centro","Nature enters the centre","La nature entre au centre","La naturaleza entra en el centro"),n("Fiume, Tivoli, Rožnik e corridoi ciclabili rendono il verde una struttura quotidiana, non una semplice escursione fuori città.","River, Tivoli, Rožnik and cycle corridors make greenery an everyday structure rather than an excursion outside town.","Rivière, Tivoli, Rožnik et corridors cyclables font du vert une structure quotidienne, pas une excursion hors ville.","Río, Tivoli, Rožnik y corredores ciclistas convierten el verde en estructura cotidiana, no excursión fuera de la ciudad.")),
 fact("🚲",n("Il centro pedonale ha cambiato le abitudini","The pedestrian centre changed habits","Le centre piéton a changé les habitudes","El centro peatonal cambió hábitos"),n("La limitazione delle auto ha favorito passeggiate, biciclette, terrazze e piccoli veicoli elettrici Kavalir per chi ha mobilità ridotta.","Restricting cars encouraged walking, cycling, terraces and small Kavalir electric vehicles for people with reduced mobility.","La limitation des voitures a favorisé marche, vélo, terrasses et petits véhicules électriques Kavalir pour mobilité réduite.","Limitar coches favoreció caminar, bicicleta, terrazas y pequeños vehículos eléctricos Kavalir para movilidad reducida.")),
 fact("📚",n("Prešeren lega poesia e identità nazionale","Prešeren links poetry and national identity","Prešeren lie poésie et identité nationale","Prešeren une poesía e identidad nacional"),n("Un verso del poeta è diventato l'inno sloveno e la sua statua guarda simbolicamente verso il ritratto dell'amata Julija.","A verse by the poet became Slovenia's anthem, and his statue symbolically looks toward a portrait of his beloved Julija.","Un vers du poète devint l'hymne slovène et sa statue regarde symboliquement le portrait de sa bien-aimée Julija.","Un verso del poeta se convirtió en himno esloveno y su estatua mira simbólicamente al retrato de su amada Julija.")),
 fact("🧱",n("Emona precede Lubiana","Emona predates Ljubljana","Emona précède Ljubljana","Emona precede a Liubliana"),n("La città romana aveva mura, strade e case nell'area occidentale del centro attuale; frammenti restano visibili in più siti.","The Roman town had walls, streets and houses in the western part of today's centre; fragments remain visible at several sites.","La ville romaine avait murs, rues et maisons dans l'ouest du centre actuel; des fragments restent visibles sur plusieurs sites.","La ciudad romana tenía murallas, calles y casas en el oeste del centro actual; quedan fragmentos visibles en varios lugares.")),
 fact("🎨",n("Metelkova nasce da una caserma occupata","Metelkova grew from occupied barracks","Metelkova naît d'une caserne occupée","Metelkova nace de un cuartel ocupado"),n("Dopo l'indipendenza, artisti e attivisti impedirono la demolizione e crearono uno dei principali spazi culturali autonomi regionali.","After independence, artists and activists stopped demolition and created one of the region's major autonomous cultural spaces.","Après l'indépendance, artistes et militants empêchèrent la démolition et créèrent un grand espace culturel autonome régional.","Tras la independencia, artistas y activistas frenaron la demolición y crearon uno de los grandes espacios culturales autónomos regionales.")),
 fact("🍯",n("Il mercato segue stagioni e territorio","The market follows season and territory","Le marché suit saisons et territoire","El mercado sigue estaciones y territorio"),n("Prodotti di fattoria, miele, funghi e verdure cambiano durante l'anno e collegano la capitale a regioni slovene molto vicine.","Farm produce, honey, mushrooms and vegetables change through the year and connect the capital with nearby Slovenian regions.","Produits fermiers, miel, champignons et légumes changent selon l'année et relient la capitale aux régions slovènes proches.","Productos de granja, miel, setas y verduras cambian durante el año y conectan la capital con regiones eslovenas cercanas.")),
 fact("🌊",n("La Ljubljanica unisce paesaggi molto diversi","The Ljubljanica links very different landscapes","La Ljubljanica relie des paysages très différents","El Ljubljanica une paisajes muy distintos"),n("Prima di attraversare il centro, il fiume nasce nel sistema carsico e costeggia le paludi; ponti e argini urbani sono solo una parte del suo percorso.","Before crossing the centre, the river emerges from a karst system and skirts the marshes; urban bridges and embankments are only part of its course.","Avant de traverser le centre, la rivière naît d'un système karstique et longe les marais; ponts et quais urbains ne sont qu'une partie de son parcours.","Antes de cruzar el centro, el río nace en un sistema kárstico y bordea las marismas; puentes y riberas urbanas son solo parte de su recorrido.")),
 fact("🎓",n("Una capitale piccola può avere ritmo universitario","A small capital can have a university rhythm","Une petite capitale peut avoir un rythme universitaire","Una capital pequeña puede tener ritmo universitario"),n("Studenti, biblioteche e spazi culturali mantengono vivo il centro oltre il turismo, soprattutto tra Tabor, Rožna Dolina e le rive del fiume.","Students, libraries and cultural venues keep the centre active beyond tourism, especially around Tabor, Rožna Dolina and the riverbanks.","Étudiants, bibliothèques et lieux culturels animent le centre au-delà du tourisme, notamment vers Tabor, Rožna Dolina et les quais.","Estudiantes, bibliotecas y espacios culturales mantienen vivo el centro más allá del turismo, sobre todo en Tabor, Rožna Dolina y las riberas.")),
]

CITY_INFO={"city":CITY_ID,"currency":"Euro (EUR)","currency_en":"Euro (EUR)","currency_fr":"Euro (EUR)","currency_es":"Euro (EUR)","language":"Sloveno","language_en":"Slovenian","language_fr":"Slovène","language_es":"Esloveno","english_level":"alto","english_note":"L'inglese è diffuso tra giovani, servizi e attività turistiche; qualche parola slovena è apprezzata.","english_note_en":"English is widespread among younger people, services and visitor businesses; a few Slovenian words are appreciated.","english_note_fr":"L'anglais est répandu chez les jeunes, dans les services et le tourisme; quelques mots slovènes sont appréciés.","english_note_es":"El inglés está extendido entre jóvenes, servicios y turismo; se agradecen algunas palabras en esloveno.","timezone":"CET (UTC+1), CEST (UTC+2) in estate","timezone_en":"CET (UTC+1), CEST (UTC+2) in summer","timezone_fr":"CET (UTC+1), CEST (UTC+2) en été","timezone_es":"CET (UTC+1), CEST (UTC+2) en verano","voltage":"230 V, prese tipo F","voltage_en":"230 V, type F sockets","voltage_fr":"230 V, prises type F","voltage_es":"230 V, enchufes tipo F","water":"L'acqua del rubinetto è potabile e di ottima qualità; fontanelle sono diffuse nel centro.","water_en":"Tap water is safe and excellent; drinking fountains are common in the centre.","water_fr":"L'eau du robinet est potable et excellente; les fontaines sont courantes dans le centre.","water_es":"El agua del grifo es potable y excelente; hay fuentes frecuentes en el centro.","tipping":"Il servizio è incluso; arrotondare o lasciare circa il 5-10% per un buon servizio è apprezzato ma non obbligatorio.","tipping_en":"Service is included; rounding up or leaving around 5-10% for good service is appreciated but optional.","tipping_fr":"Le service est inclus; arrondir ou laisser environ 5-10% pour un bon service est apprécié mais facultatif.","tipping_es":"El servicio está incluido; redondear o dejar alrededor del 5-10% por buen servicio se agradece pero es opcional.","emergency_numbers":[{"label":"Emergenze generali","label_en":"General emergency","label_fr":"Urgences générales","label_es":"Emergencias generales","number":"112"},{"label":"Polizia","label_en":"Police","label_fr":"Police","label_es":"Policía","number":"113"}],"transport_apps":[{"name":"Urbana","description":"Pagamento e servizi per gli autobus urbani LPP e alcune funzioni cittadine.","description_en":"Payment and services for LPP city buses and selected city functions.","description_fr":"Paiement et services pour les bus urbains LPP et certaines fonctions municipales.","description_es":"Pago y servicios para autobuses urbanos LPP y algunas funciones municipales.","ios_url":"https://www.lpp.si/en/public-transport/mobile-application-urbana","android_url":"https://www.lpp.si/en/public-transport/mobile-application-urbana"}],"useful_apps":[{"name":"BicikeLJ","description":"Sistema pubblico di biciclette condivise con stazioni nel centro e nei quartieri.","description_en":"Public bike-sharing system with stations in the centre and districts.","description_fr":"Système public de vélos partagés avec stations dans le centre et les quartiers.","description_es":"Sistema público de bicicletas compartidas con estaciones en centro y barrios.","ios_url":"https://www.bicikelj.si/en/home","android_url":"https://www.bicikelj.si/en/home"}],"quick_tips":["Il centro è pedonale: usa autobus o bici per i quartieri, poi prosegui a piedi.","Sugli autobus valida Urbana a ogni salita.","Mercato Centrale è più vivo al mattino e quasi fermo la domenica.","Per castello e Rožnik considera il dislivello oltre ai chilometri.","Palude e sentieri periferici richiedono meteo stabile e una pianificazione separata."],"quick_tips_en":["The centre is pedestrian: use bus or bike for districts, then continue on foot.","Validate Urbana every time you board a bus.","The Central Market is liveliest in the morning and mostly inactive on Sundays.","For the castle and Rožnik, account for elevation as well as distance.","Marshes and outer trails need stable weather and separate planning."],"quick_tips_fr":["Le centre est piéton: prenez bus ou vélo vers les quartiers, puis marchez.","Validez Urbana à chaque montée dans le bus.","Le Marché central est plus vivant le matin et presque inactif le dimanche.","Pour château et Rožnik, comptez le dénivelé autant que la distance.","Marais et sentiers périphériques demandent météo stable et planification séparée."],"quick_tips_es":["El centro es peatonal: usa bus o bici para barrios y continúa a pie.","Valida Urbana cada vez que subas al autobús.","El Mercado Central está más vivo por la mañana y casi inactivo el domingo.","Para castillo y Rožnik considera desnivel además de distancia.","Marismas y senderos periféricos requieren tiempo estable y planificación separada."]}

NEIGHBORHOODS=[
 neighborhood(51,CITY_ID,n("Centro storico","Old Town","Vieille Ville","Casco antiguo"),n("Pro: attrazioni, fiume e ristoranti tutti a piedi. Pro: centro pedonale e atmosfera serale. Contro: prezzi più elevati e folla stagionale. Contro: accesso auto e parcheggio difficili.","Pros: sights, river and restaurants all walkable. Pros: pedestrian centre and evening atmosphere. Cons: higher prices and seasonal crowds. Cons: difficult car access and parking.","Avantages: sites, rivière et restaurants à pied. Avantages: centre piéton et ambiance du soir. Inconvénients: prix élevés et foule saisonnière. Inconvénients: accès voiture et stationnement difficiles.","Ventajas: monumentos, río y restaurantes a pie. Ventajas: centro peatonal y ambiente nocturno. Desventajas: precios altos y multitudes estacionales. Desventajas: acceso en coche y aparcamiento difíciles."),["centrale","attrazioni","gastronomico"]),
 neighborhood(52,CITY_ID,n("Tabor e Metelkova","Tabor and Metelkova","Tabor et Metelkova","Tabor y Metelkova"),n("Pro: stazione, musei e cultura indipendente vicini. Pro: alloggi spesso meno costosi del fiume. Contro: rumore notturno attorno a Metelkova. Contro: area della stazione in trasformazione.","Pros: station, museums and independent culture nearby. Pros: often cheaper than the riverfront. Cons: night noise around Metelkova. Cons: station area under transformation.","Avantages: gare, musées et culture indépendante proches. Avantages: souvent moins cher que les quais. Inconvénients: bruit nocturne à Metelkova. Inconvénients: secteur de gare en transformation.","Ventajas: estación, museos y cultura independiente cerca. Ventajas: a menudo más barato que el río. Desventajas: ruido nocturno en Metelkova. Desventajas: zona de estación en transformación."),["arte","vita notturna","trasporti"]),
 neighborhood(53,CITY_ID,n("Trnovo e Krakovo","Trnovo and Krakovo","Trnovo et Krakovo","Trnovo y Krakovo"),n("Pro: atmosfera residenziale, fiume e Plečnik. Pro: centro raggiungibile a piedi o in bici. Contro: pochi hotel e servizi serali. Contro: distanze maggiori dalla stazione.","Pros: residential atmosphere, river and Plečnik. Pros: centre walkable or bikeable. Cons: few hotels and evening services. Cons: farther from the station.","Avantages: ambiance résidentielle, rivière et Plečnik. Avantages: centre à pied ou vélo. Inconvénients: peu d'hôtels et services le soir. Inconvénients: plus loin de la gare.","Ventajas: ambiente residencial, río y Plečnik. Ventajas: centro a pie o en bici. Desventajas: pocos hoteles y servicios nocturnos. Desventajas: más lejos de la estación."),["residenziale","tranquillo","culturale"]),
 neighborhood(54,CITY_ID,n("Šiška","Šiška","Šiška","Šiška"),n("Pro: cultura contemporanea, verde e vita locale. Pro: autobus e bici verso il centro. Contro: poche attrazioni classiche immediate. Contro: traffico sugli assi principali.","Pros: contemporary culture, greenery and local life. Pros: buses and bikes to centre. Cons: few classic sights nearby. Cons: traffic on main roads.","Avantages: culture contemporaine, verdure et vie locale. Avantages: bus et vélos vers le centre. Inconvénients: peu de sites classiques proches. Inconvénients: trafic sur les grands axes.","Ventajas: cultura contemporánea, verde y vida local. Ventajas: buses y bici al centro. Desventajas: pocos monumentos clásicos cerca. Desventajas: tráfico en vías principales."),["arte","residenziale","trasporti"]),
 neighborhood(55,CITY_ID,n("Tivoli e Rožna Dolina","Tivoli and Rožna Dolina","Tivoli et Rožna Dolina","Tivoli y Rožna Dolina"),n("Pro: parco, musei e ambiente tranquillo. Pro: centro vicino senza essere nel rumore. Contro: ristoranti serali meno numerosi. Contro: alcune strutture sono distanti dalle fermate.","Pros: park, museums and quiet setting. Pros: near centre without its noise. Cons: fewer evening restaurants. Cons: some lodging is far from stops.","Avantages: parc, musées et calme. Avantages: proche du centre sans son bruit. Inconvénients: moins de restaurants le soir. Inconvénients: certains logements loin des arrêts.","Ventajas: parque, museos y tranquilidad. Ventajas: cerca del centro sin su ruido. Desventajas: menos restaurantes nocturnos. Desventajas: algunos alojamientos lejos de paradas."),["verde","tranquillo","culturale"]),
 neighborhood(56,CITY_ID,n("Bežigrad","Bežigrad","Bežigrad","Bežigrad"),n("Pro: collegamenti autobus, stazione e servizi quotidiani. Pro: alloggi spesso funzionali e meno turistici. Contro: centro storico non sempre comodo a piedi. Contro: atmosfera più urbana che pittoresca.","Pros: bus links, station and everyday services. Pros: often functional and less touristic lodging. Cons: old town not always comfortably walkable. Cons: urban rather than picturesque atmosphere.","Avantages: bus, gare et services quotidiens. Avantages: logements fonctionnels et moins touristiques. Inconvénients: vieille ville pas toujours proche à pied. Inconvénients: ambiance plus urbaine que pittoresque.","Ventajas: buses, estación y servicios cotidianos. Ventajas: alojamiento funcional y menos turístico. Desventajas: casco antiguo no siempre cómodo a pie. Desventajas: ambiente más urbano que pintoresco."),["trasporti","budget","residenziale"]),
]
